import { useCurrentTheme } from '../../../../../core/hooks/useCurrentTheme.js';
import { getMarkerBrightnessBasedOnState } from '../functions/get-marker-brightness-based-on-state.js';
import { MarkerInteractionState } from '../types/marker.js';

export const MARKER_DEFAULT_OPACITY = 1;
export const MARKER_HOVER_OPACITY = 0.2;

/**
 * Returns the proper opacity and slope for the BrightnessFilter depending on theme and marker state
 * @param state -
 */
export function useMarkerBrightness(state: MarkerInteractionState) {
  const theme = useCurrentTheme();

  const opacity =
    state === 'inactive' ? MARKER_HOVER_OPACITY : MARKER_DEFAULT_OPACITY;

  return { opacity, slope: getMarkerBrightnessBasedOnState(theme, state) };
}
